<div class="container py-4"><div class="mb-4"><div class="text-muted small"><?=e($client['company_name'])?></div><h1 class="h3"><?=e($title)?></h1></div><form method="post" action="<?= $assessment?'assessments/update':'assessments/store' ?>" class="card border-0 shadow-sm"><div class="card-body"><input type="hidden" name="client_id" value="<?=(int)$client['id']?>"><?php if($assessment):?><input type="hidden" name="id" value="<?=(int)$assessment['id']?>"><?php endif;?><?php include __DIR__.'/../partials/csrf.php';?><div class="row g-3"><div class="col-md-7"><label class="form-label">Title *</label><input required name="title" class="form-control" value="<?=e($assessment['title']??'')?>"></div><div class="col-md-5"><label class="form-label">Assessment type</label><select name="assessment_type" class="form-select"><?php foreach(['privacy_review','dpia','vendor_review','transfer_review','other'] as $v):?><option value="<?=$v?>" <?=($assessment['assessment_type']??'privacy_review')===$v?'selected':''?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach(['draft','in_progress','completed','approved','archived'] as $v):?><option value="<?=$v?>" <?=($assessment['status']??'draft')===$v?'selected':''?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Processing activity</label><select name="processing_activity_id" class="form-select"><option value="">None</option><?php foreach($activities as $a):?><option value="<?=(int)$a['id']?>" <?=((int)($assessment['processing_activity_id']??0)===(int)$a['id'])?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Risk score (0–100)</label><input type="number" min="0" max="100" step="0.01" name="risk_score" class="form-control" value="<?=e((string)($assessment['risk_score']??''))?>"></div><div class="col-md-6"><label class="form-label">Due date</label><input type="date" name="due_date" class="form-control" value="<?=e($assessment['due_date']??'')?>"></div><div class="col-md-6"><label class="form-label">Findings</label><textarea name="findings" class="form-control" rows="3"><?=e($assessment['findings']??'')?></textarea></div><div class="col-12"><label class="form-label">Recommendations</label><textarea name="recommendations" class="form-control" rows="3"><?=e($assessment['recommendations']??'')?></textarea></div></div></div><div class="card-footer bg-white d-flex justify-content-between"><a class="btn btn-outline-secondary" href="assessments?client_id=<?=(int)$client['id']?>">Cancel</a><button class="btn btn-primary">Save assessment</button></div></form></div>
